48:   if (typeof expression !== 'string' && (typeof expression !== 'object' || !expression || !('type' in expression))) {
49:     throw `Unknown expression type ${expression}. Expressions must either be a string or pre-compiled string.`;
50:   }
51: 
52:   const context = createAsynchronousContext();
53:   visitExpression(typeof expression === 'string' ? jsep(expression) : expression, context);
54: 
55:   return [...context.variables];
56: }
